import assert from 'node:assert/strict';
import { test } from 'vitest';
import {
  activateCard,
  advanceGame,
  createGame,
  faceUpCards,
  isWon,
  MISMATCH_MS,
  ELAPSED_MAX_MS,
} from './game.ts';
import { SelectionKind } from './selection.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS, SPEC_VECTOR } from './game.fixture.ts';
import { formatElapsed } from './elapsed-time.ts';
import type { GameState } from './game.ts';

test('first reveal starts play without a move and ignores invalid activation', () => {
  const start = createGame(EXAMPLE_CODE);
  assert.equal(advanceGame(start, 300), start);
  const first = activateCard(start, 2);
  assert.equal(first.started, true, 'R07 first reveal starts time');
  assert.deepEqual(first.selection, { kind: SelectionKind.one, index: 2 });
  for (const index of [2, -1, 16, 0.5, NaN, Infinity])
    assert.equal(activateCard(first, index), first);
  assert.equal(first.moves, 0);
  assert.equal(activateCard(first, 6).moves, 1, 'R05 a different second card costs one move');
  assert.equal(start.started, false);
});

test('a matching pair stays up and costs exactly one move', () => {
  const result = activateCard(activateCard(createGame(EXAMPLE_CODE), 2), 6);
  assert.deepEqual(result.matched, [2, 6], 'R03 matching pair stays matched');
  assert.equal(result.selection.kind, SelectionKind.closed);
  assert.equal(result.moves, 1, 'R05 second distinct reveal adds one move');
  assert.equal(activateCard(result, 6), result);
});

test('a mismatch blocks all activation and closes together at the exact interval', () => {
  assert.equal(MISMATCH_MS, SPEC_VECTOR.mismatchMs);
  const mismatch = activateCard(activateCard(createGame(EXAMPLE_CODE), 0), 1);
  assert.equal(mismatch.moves, 1);
  for (const index of [0, 1, 2, 6])
    assert.equal(activateCard(mismatch, index), mismatch, 'R04 mismatch blocks activation');
  const pending = advanceGame(mismatch, SPEC_VECTOR.mismatchMs - 1);
  assert.deepEqual(pending.selection, {
    kind: SelectionKind.mismatch,
    first: 0,
    second: 1,
    remainingMs: 1,
  });
  const closed = advanceGame(pending, 1);
  assert.equal(closed.selection.kind, SelectionKind.closed, 'R04 mismatch closes at 800ms');
  assert.equal(closed.elapsedMs, SPEC_VECTOR.mismatchMs);
  assert.equal(activateCard(closed, 2).selection.kind, SelectionKind.one);
});

test('completion counts only matched pairs and stops the clock and later activation', () => {
  let state = createGame(EXAMPLE_CODE);
  for (const [first, second] of EXAMPLE_PAIRS) {
    state = activateCard(advanceGame(activateCard(state, first), 10), second);
  }
  assert.equal(isWon(state), true);
  assert.equal(state.matched.length / 2, EXAMPLE_PAIRS.length);
  assert.equal(state.moves, EXAMPLE_PAIRS.length);
  assert.equal(state.elapsedMs, 80);
  assert.equal(advanceGame(state, 100), state);
  assert.equal(activateCard(state, 0), state);
});

test('new states keep earlier games unchanged and reject invalid elapsed input', () => {
  const old = activateCard(activateCard(createGame(EXAMPLE_CODE), 0), 1);
  const current = createGame(EXAMPLE_CODE);
  advanceGame(old, MISMATCH_MS);
  assert.deepEqual(current, createGame(EXAMPLE_CODE));
  for (const delta of [-1, 0, Infinity, NaN]) assert.equal(advanceGame(old, delta), old);
  const capped = advanceGame({ ...old, elapsedMs: ELAPSED_MAX_MS - 1 }, Number.MAX_SAFE_INTEGER);
  assert.equal(capped.elapsedMs, ELAPSED_MAX_MS);
  assert.equal(capped.selection.kind, SelectionKind.closed);
  assert.equal(activateCard(capped, 2).selection.kind, SelectionKind.one);
  assert.equal(formatElapsed(capped.elapsedMs), '5999:59');
});

test('one active-time step advances elapsed and mismatch together', () => {
  const old = activateCard(activateCard(createGame(EXAMPLE_CODE), 0), 1);
  const before = advanceGame(old, 799);
  assert.equal(before.elapsedMs, 799);
  assert.deepEqual(before.selection, {
    kind: SelectionKind.mismatch,
    first: 0,
    second: 1,
    remainingMs: 1,
  });
  assert.equal(advanceGame(before, 1).selection.kind, SelectionKind.closed);
});

test('a card faces up while it is the one selection, either mismatch card or matched', () => {
  const faceUp = (state: GameState) => [...faceUpCards(state)].sort((left, right) => left - right);
  const start = createGame(EXAMPLE_CODE);
  assert.deepEqual(faceUp(start), []);
  const one = activateCard(start, 0);
  assert.deepEqual(faceUp(one), [0]);
  const mismatch = activateCard(one, 1);
  assert.deepEqual(faceUp(mismatch), [0, 1]);
  const matched = activateCard(activateCard(advanceGame(mismatch, MISMATCH_MS), 2), 6);
  assert.deepEqual(faceUp(matched), [2, 6]);
});
import assert from 'node:assert/strict';
import { test } from 'vitest';
import {
  DEFAULT_SIZE,
  PREFERENCES_KEY,
  PREFERENCES_VERSION,
  readPreferences,
  rememberBest,
  writePreferences,
} from './storage.ts';
import { MOVES_MAX } from '../game.ts';
import { SPEC_VECTOR } from '../game.fixture.ts';
import type { PreferenceStore } from './storage.ts';

function memoryStore(initial = ''): PreferenceStore {
  const entries = new Map([[PREFERENCES_KEY, initial]]);
  return {
    getItem: (key) => entries.get(key) ?? null,
    setItem: (key, value) => {
      entries.set(key, value);
    },
  };
}

test('preferences round trip size and separate minimum moves per size', () => {
  const store = memoryStore();
  const preferences = rememberBest(rememberBest({ size: 6, bestMoves: {} }, 4, 12), 6, 20);
  writePreferences(store, preferences);
  assert.deepEqual(readPreferences(store), preferences, 'R10 scores survive storage round trip');
  assert.equal(rememberBest(preferences, 4, 13), preferences, 'R10 worse score keeps best');
  assert.equal(rememberBest(preferences, 4, 12), preferences);
  assert.equal(rememberBest(preferences, 4, 9).bestMoves['4'], 9, 'R10 better score replaces best');
  assert.equal(preferences.bestMoves['6'], 20, 'R10 size six has its separate best');
});

test('a best at the move cap round trips and a larger saved best is ignored', () => {
  const store = memoryStore();
  const capped = { size: DEFAULT_SIZE, bestMoves: { [DEFAULT_SIZE]: MOVES_MAX } };
  writePreferences(store, capped);
  assert.deepEqual(readPreferences(store), capped);
  assert.equal(rememberBest(capped, DEFAULT_SIZE, MOVES_MAX), capped);
  const larger = {
    schemaVersion: PREFERENCES_VERSION,
    size: DEFAULT_SIZE,
    bestMoves: { [DEFAULT_SIZE]: MOVES_MAX + 1 },
  };
  store.setItem(PREFERENCES_KEY, JSON.stringify(larger));
  assert.deepEqual(readPreferences(store), { size: DEFAULT_SIZE, bestMoves: {} });
});

const INVALID_PREFERENCES = [
  '{',
  'null',
  '{}',
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 5, bestMoves: {} }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: 1 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: -1 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: 8.5 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { '04': 8 } }),
];
for (const [index, text] of INVALID_PREFERENCES.entries()) {
  test(`preferences ignore invalid saved data ${index + 1}`, () => {
    assert.deepEqual(readPreferences(memoryStore(text)), { size: DEFAULT_SIZE, bestMoves: {} });
  });
}

test('storage failures keep play available and never change unrelated keys', () => {
  const denied: PreferenceStore = {
    getItem: () => {
      throw new Error();
    },
    setItem: () => {
      throw new Error();
    },
  };
  assert.equal(DEFAULT_SIZE, SPEC_VECTOR.sizes[0]);
  assert.equal(readPreferences(denied).size, DEFAULT_SIZE);
  assert.doesNotThrow(() => writePreferences(denied, { size: DEFAULT_SIZE, bestMoves: {} }));
  assert.equal(readPreferences(null).size, DEFAULT_SIZE);
  const store = memoryStore();
  const unrelated = 'another-application';
  store.setItem(unrelated, 'kept');
  writePreferences(store, { size: DEFAULT_SIZE, bestMoves: {} });
  assert.equal(store.getItem(unrelated), 'kept');
});
import { expect, test } from './browser-test.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS } from '../src/game/game.fixture.ts';
